<?php
/**
 * Nexopay Live Deploy Script 🚀
 * Place this in public_html and visit yoursite.com/live_deploy.php
 * It configures DB files (which are git ignored) and syncs the exact Local Events.
 */
session_start();
$step = isset($_GET['step']) ? (int)$_GET['step'] : 1;
$error = '';
$success = '';

// We inject the base64 string containing local events here
$b64_data = "﻿﻿";

$db1 = 'includes/db.php';
$db2 = 'nexopay.com.bd/config/database.php';
$db3 = 'nexopay.com.bd/config/nexorah_db.php';

$missingFiles = [];
if (!file_exists($db1)) $missingFiles[] = $db1;
if (!file_exists($db2)) $missingFiles[] = $db2;
if (!file_exists($db3)) $missingFiles[] = $db3;

if ($_SERVER['REQUEST_METHOD'] === 'POST' && $step == 1) {
    if (isset($_POST['setup_configs'])) {
        $host = $_POST['host'] ?? 'localhost';
        
        $nexorah_db = $_POST['nexorah_db'] ?? '';
        $nexorah_user = $_POST['nexorah_user'] ?? '';
        $nexorah_pass = $_POST['nexorah_pass'] ?? '';
        
        $nexopay_db = $_POST['nexopay_db'] ?? '';
        $nexopay_user = $_POST['nexopay_user'] ?? '';
        $nexopay_pass = $_POST['nexopay_pass'] ?? '';

        // Write includes/db.php
        $db1_content = "<?php\n\$host = '$host';\n\$dbname = '$nexorah_db';\n\$username = '$nexorah_user';\n\$password = '$nexorah_pass';\ntry { \$pdo = new PDO(\"mysql:host=\$host;dbname=\$dbname;charset=utf8mb4\", \$username, \$password); \$pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION); } catch (PDOException \$e) { die(\"DB Error: \" . \$e->getMessage()); }\n";
        
        if (!is_dir('includes')) mkdir('includes', 0755, true);
        file_put_contents($db1, $db1_content);

        // Write nexopay.com.bd/config/database.php
        $db2_content = "<?php\nclass Database {\n private \$host = '$host';\n private \$db_name = '$nexopay_db';\n private \$username = '$nexopay_user';\n private \$password = '$nexopay_pass';\n private \$conn;\n public function getConnection() {\n \$this->conn = null;\n try {\n \$dsn = \"mysql:host={\$this->host};dbname={\$this->db_name};charset=utf8mb4\";\n \$options = [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC];\n \$this->conn = new PDO(\$dsn, \$this->username, \$this->password, \$options);\n } catch(PDOException \$e) { die(\"Connection error: \" . \$e->getMessage()); }\n return \$this->conn;\n }\n}\n?>";
        
        if (!is_dir('nexopay.com.bd/config')) mkdir('nexopay.com.bd/config', 0755, true);
        file_put_contents($db2, $db2_content);

        // Write nexopay.com.bd/config/nexorah_db.php
        // Uses the same PDO structure as db1
        $db3_content = "<?php\ntry {\n \$pdo = new PDO(\"mysql:host=$host;dbname=$nexorah_db;charset=utf8mb4\", '$nexorah_user', '$nexorah_pass');\n \$pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);\n \$pdo->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE, PDO::FETCH_ASSOC);\n} catch (PDOException \$e) { die(\"Database connection error: \" . \$e->getMessage()); }\n?>";
        file_put_contents($db3, $db3_content);

        header("Location: ?step=2");
        exit;
    }
}

if ($step == 2) {
    try {
        require_once $db1;
        $nexorah_pdo = $pdo;
    } catch(Exception $e) {
        $error = "Failed to load Nexorah DB: " . $e->getMessage();
    }

    try {
        require_once $db2;
        $dbObj = new Database();
        $nexopay_pdo = $dbObj->getConnection();
    } catch(Exception $e) {
        $error = "Failed to load Nexopay DB: " . $e->getMessage();
    }

    if (!$error && $nexorah_pdo && $nexopay_pdo) {
        $data = json_decode(base64_decode($b64_data), true);
        
        function insertOrUpdateEvent($pdo, $event) {
            $cols = array_keys($event);
            foreach($cols as $k => $v) if($v === 'id') unset($cols[$k]); 
            // Keep ID inside event data to insert explicitly, but we build SET query dynamically.
            $cols = array_keys($event); 
            
            $placeholders = implode(', ', array_fill(0, count($cols), '?'));
            $colNames = implode(', ', array_map(function($c) { return "`$c`"; }, $cols));
            
            $updateStmts = [];
            foreach($cols as $c) {
                if ($c !== 'id') {
                    $updateStmts[] = "`$c` = VALUES(`$c`)";
                }
            }
            $updateStr = implode(', ', $updateStmts);
            
            $sql = "INSERT INTO events ($colNames) VALUES ($placeholders) ON DUPLICATE KEY UPDATE $updateStr";
            $stmt = $pdo->prepare($sql);
            $stmt->execute(array_values($event));
        }

        // Migrate Nexorah
        foreach ($data['nexorah_events'] as $e) {
            insertOrUpdateEvent($nexorah_pdo, $e);
        }

        // Migrate Nexopay
        foreach ($data['nexopay_events'] as $e) {
            insertOrUpdateEvent($nexopay_pdo, $e);
        }

        // Ensure Admin exists in Nexopay
        $cmd = "CREATE TABLE IF NOT EXISTS admin_users (
            id INT PRIMARY KEY AUTO_INCREMENT,
            username VARCHAR(50) UNIQUE NOT NULL,
            password VARCHAR(255) NOT NULL,
            email VARCHAR(100) NOT NULL,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            last_login TIMESTAMP NULL,
            is_active BOOLEAN DEFAULT TRUE
        )";
        $nexopay_pdo->exec($cmd);

        $stmt = $nexopay_pdo->query("SELECT id FROM admin_users WHERE username='admin'");
        if (!$stmt->fetch()) {
            $pass = password_hash('admin123', PASSWORD_DEFAULT);
            $nexopay_pdo->exec("INSERT INTO admin_users (username, password, email) VALUES ('admin', '$pass', 'admin@nexopay.com')");
        }

        $success = "Database configuration setup and event data synchronization complete! You can now access your live site. <b>Please delete this file (live_deploy.php) from the server for security.</b>";
        $missingFiles = [];
    }
}
?>
